530	static int remote_ctrl_pending_from_input(void *ctx)
531	{
532	    (void)ctx;
533	    struct remote_status_s st;
534	
535	    if (g_debug_pending)
536	        return 1;
537	
538	    if (!g_configured)
539	        return 0;
540	
541	    if (remote_ctrl_channel_status(&st) != OK)
542	        return 0;
543	
544	    return st.has_prompt ? 1 : 0;
545	}
