547	static void remote_ctrl_decide_from_input(enum remote_decision_e decision,
548	                                          void *ctx)
549	{
550	    (void)ctx;
551	
552	    if (g_debug_pending) {
553	        /* A simulated approval (rpending): answer it locally.  There is no
554	         * real prompt in the session, so remote_ctrl_channel_decide() would
555	         * only report "nothing pending". */
556	        g_debug_pending = false;
557	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
558	        lvgl_ui_channel_clear_approval();
559	        lvgl_toast_show_async("审批",
560	                              decision == REMOTE_DECISION_DENY ? "已取消"
561	                                                               : "已通过",
562	                              decision == REMOTE_DECISION_DENY ? 0xeb5952
563	                                                               : 0x4caf50,
564	                              2000);
565	#endif
566	        printf(decision == REMOTE_DECISION_DENY ? "Denied (debug).\n"
567	                                                : "Approved once (debug).\n");
568	        return;
569	    }
570	
571	    if (remote_ctrl_channel_decide(decision) != OK) {
572	        printf("No approvable request is pending (or one was already "
573	               "answered).\n");
574	        return;
575	    }
576	
577	    printf(decision == REMOTE_DECISION_DENY ? "Denied.\n"
578	                                            : "Approved once.\n");
579	}
