591	static void remote_ctrl_model_next_from_input(void *ctx)
592	{
593	    (void)ctx;
594	    /* Larger than the 4 KB key-thread stack: keep it static. */
595	    static struct remote_model_view_s view;
596	    unsigned int i;
597	    unsigned int next;
598	
599	    if (remote_ctrl_channel_model_view(&view) != OK || view.count == 0) {
600	        printf("No model list to cycle (channel unconfigured?).\n");
601	        return;
602	    }
603	
604	    for (i = 0; i < view.count; i++) {
605	        if (strcmp(view.options[i], view.current) == 0)
606	            break;
607	    }
608	    next = (i == view.count ? 0 : (i + 1) % view.count);
609	
610	    if (remote_ctrl_channel_select_model(view.options[next]) != OK) {
611	        printf("Model switch request failed.\n");
612	        return;
613	    }
614	    printf("Model -> %s\n", view.options[next]);
615	}
