727	/* Idle-yield support: when the pet status ring is enabled, the chat screen
728	 * yields the foreground to the pet after PET_IDLE_YIELD_MS of message silence.
729	 * All access is confined to the LVGL thread (init creates the timer; the send
730	 * async cb resets the tick; the timer cb does the yield). */
731	static lv_timer_t *s_pet_idle_timer = NULL;
732	static uint32_t    s_pet_last_msg_tick = 0;
733	
734	static void pet_idle_timer_cb(lv_timer_t *t)
735	{
736	    (void)t;
737	    if (!s_state.initialized || !s_state.screen_visible) return;
738	    /* A pending remote permission request owns the foreground: never yield it
739	     * back to the pet home screen while the approval page is up, or the user
740	     * loses the S2/S3 approve/cancel cue mid-decision. */
741	    if (s_state.approval_visible) return;
742	    /* Judge by the active screen, not the cached visible flag: opening the
743	     * chat screen does not call pet_status_view_hide(), so the flag stays true
744	     * and the yield below would never fire (blank chat page stuck forever). */
745	    if (!pet_status_view_is_active() &&
746	        (lv_tick_get() - s_pet_last_msg_tick) >= PET_IDLE_YIELD_MS)
747	      {
748	        /* Yield: the chat screen stays alive but releases the foreground so
749	         * the pet home screen shows.  Clearing screen_visible lets the next
750	         * incoming message re-take the foreground via lvgl_ui_channel_show. */
751	        s_state.screen_visible = false;
752	        pet_status_view_show();
753	        syslog(LOG_INFO, "[%s] idle → pet home screen\n", TAG);
754	      }
755	}
