1	/****************************************************************************
2	 * board/bk7258-devkit/src/bk7258_buttons_input.c
3	 *
4	 * A /dev/btn0 reader, a gesture engine on top of it, and a context stack
5	 * of key maps.
6	 *
7	 * Why the shape:
8	 *   - /dev/btn0 takes several readers: the upper half allocates a
9	 *     btn_open_s per open() with its own pending flag and notifies every
10	 *     open (drivers/input/button_upper.c).  ai_agent's ptt_button thread
11	 *     opens it separately for KEY1 (push-to-talk); this file owns KEY2/KEY3.
12	 *   - The gesture layer reports TAP/HOLD/DOUBLE/COMBO from that snapshot.
13	 *     LVGL's indev wants a state not an event stream too, so the two layer
14	 *     cleanly once it arrives.
15	 *   - What a key means depends on the screen.  Each context owns its own
16	 *     key map; a small global layer is consulted first so an escape hatch
17	 *     (cancel, leave) always works no matter which page is up.
18	 *
19	 * Keys (board.h): BUTTON_KEY1/2/3 on GPIO 13/12/8, active low.
20	 ****************************************************************************/
21	
22	#include <nuttx/config.h>
23	
24	#include <errno.h>
25	#include <fcntl.h>
26	#include <poll.h>
27	#include <pthread.h>
28	#include <stdio.h>
29	#include <string.h>
30	#include <unistd.h>
31	#include <sys/ioctl.h>
32	
33	#include <nuttx/input/buttons.h>
34	
35	#include <arch/chip/bk7258_memorymap.h>
36	
37	#include "board.h"
38	
39	/* The remote_ctrl input-adapter surface.  This file is a keymap adapter:
40	 * it maps gestures onto the application intents it is handed -- decide,
41	 * pending, scroll, model-next, new-session -- and registers itself through
42	 * remote_ctrl_register_input().  A touch-screen adapter would be a sibling
43	 * doing the same thing with widget events; remote_ctrl never learns which
44	 * hardware the product has.
45	 */
46	
47	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
48	enum remote_decision_e
49	{
50	  REMOTE_DECISION_ONCE = 0,
51	  REMOTE_DECISION_DENY,
52	};
53	
54	typedef void (*remote_decide_fn)(enum remote_decision_e decision, void *ctx);
55	typedef int  (*remote_pending_fn)(void *ctx);
56	typedef void (*remote_scroll_fn)(int dir, void *ctx);
57	typedef void (*remote_action_fn)(void *ctx);
58	
59	struct remote_input_ops_s
60	{
61	  const char *name;
62	  int (*attach)(remote_decide_fn decide,
63	                remote_pending_fn pending,
64	                remote_scroll_fn scroll,
65	                remote_action_fn model_next,
66	                remote_action_fn session_new,
67	                void *ctx);
68	  void (*detach)(void);
69	};
70	
71	int remote_ctrl_register_input(const struct remote_input_ops_s *ops);
72	
73	#endif
