76	/****************************************************************************
77	 * Pre-processor Definitions
78	 ****************************************************************************/
79	
80	#define GESTURE_HOLD_MS     800
81	#define GESTURE_DOUBLE_MS   400
82	#define POLL_SLICE_MS       20
83	#define LED_SLICE_TICKS     2   /* 2 x 20 ms = 40 ms */
84	
85	#define KEY_COUNT           NUM_BUTTONS
86	#define KEY_BIT(i)          (1u << (i))
87	
88	#define GLOBAL_MAP_NAME     "global"
89	#define IDLE_MAP_NAME       "idle"
90	
91	/****************************************************************************
92	 * Public Types
93	 ****************************************************************************/
94	
95	enum gesture_e
96	{
97	  GESTURE_TAP = 0,   /* press and release inside HOLD */
98	  GESTURE_HOLD,      /* held past GESTURE_HOLD_MS */
99	  GESTURE_DOUBLE,    /* two taps inside DOUBLE_MS */
100	  GESTURE_COMBO,     /* two or more keys pressed together */
101	  GESTURE_PRESS,     /* key went down -- the front half of press-and-hold */
102	  GESTURE_RELEASE,   /* key came up -- the back half */
103	};
104	
105	typedef void (*key_action_t)(void);
106	
107	struct keymap_s
108	{
109	  uint32_t       keys;   /* button bitmask, one bit for TAP/HOLD/DOUBLE */
110	  enum gesture_e gesture;
111	  key_action_t   fn;
112	};
113	
114	struct keyctx_s
115	{
116	  const char          *name;
117	  const struct keymap_s *map;
118	  unsigned int         nmap;
119	  void               (*enter)(void);
120	  void               (*leave)(void);
121	};
