123	/****************************************************************************
124	 * Private Data
125	 ****************************************************************************/
126	
127	static int s_fd = -1;
128	static uint32_t s_held;          /* currently down */
129	static uint32_t s_prev;          /* previous snapshot, for edges */
130	static uint32_t s_down_ms[KEY_COUNT];
131	static bool s_tap_pending[KEY_COUNT];
132	static bool s_hold_fired[KEY_COUNT];
133	static uint32_t s_combo_started;
134	static uint32_t s_irq_held;      /* state as of the last POLLIN */
135	static uint32_t s_skew_ms;
136	static bool s_skew;
137	static bool s_skew_reported;
