142	/****************************************************************************
143	 * Context stack
144	 *
145	 * Lookup walks from the top downwards so a page overrides the global layer.
146	 * The global map holds only the escape hatches.
147	 ****************************************************************************/
148	
149	static void action_cancel(void);
150	/* ponytail: diagnostic for the lost KEY3 (GPIO8) release edge.  GPIO8 is
151	 * also Armino's ADC10 pin, and Armino's gpio_dev_map()/unmap() clear the
152	 * pin's int_en (bit 12) and rewrite its mux.  Dump CFG and the mux word
153	 * when an edge goes missing so the board log shows who flips them.  Remove
154	 * once the writer is found.
155	 */
156	
157	static void key3_regs(const char *tag)
158	{
159	  printf("[key] %s gpio%d cfg=%08lx func=%08lx\n", tag, BOARD_KEY3_PIN,
160	         (unsigned long)*(volatile uint32_t *)
161	           BK7258_GPIO_CFG(BOARD_KEY3_PIN),
162	         (unsigned long)*(volatile uint32_t *)
163	           BK7258_SYS_GPIO_FUNC(BOARD_KEY3_PIN));
164	}
