166	static void action_once(void);
167	static void action_deny(void);
168	static void action_scroll_up(void);
169	static void action_scroll_down(void);
170	static void action_model(void);
171	static void action_session(void);
172	
173	static const struct keymap_s g_global_map[] =
174	{
175	  { KEY_BIT(1) | KEY_BIT(2), GESTURE_COMBO, action_cancel },
176	};
177	
178	/* Idle: KEY2/KEY3 scroll the chat transcript on a tap, or cycle the remote
179	 * model / open a fresh session on a hold.  KEY1 (GPIO13) is push-to-talk,
180	 * owned by ai_agent's ptt_button thread on its own /dev/btn0 open. */
181	static const struct keymap_s g_idle_map[] =
182	{
183	  { KEY_BIT(1), GESTURE_TAP,    action_scroll_up },
184	  { KEY_BIT(2), GESTURE_TAP,    action_scroll_down },
185	  { KEY_BIT(1), GESTURE_HOLD,   action_model },
186	  { KEY_BIT(2), GESTURE_HOLD,   action_session },
187	};
188	
189	/* Approval: pushed on top of idle while a permission request is pending, so
190	 * the same two keys answer it instead of scrolling. */
191	static const struct keymap_s g_approval_map[] =
192	{
193	  { KEY_BIT(1), GESTURE_TAP,    action_once },
194	  { KEY_BIT(2), GESTURE_TAP,    action_deny },
195	};
196	
197	static const struct keyctx_s g_global_ctx =
198	{
199	  GLOBAL_MAP_NAME, g_global_map,
200	  sizeof(g_global_map) / sizeof(g_global_map[0]), NULL, NULL
201	};
202	
203	static const struct keyctx_s g_idle_ctx =
204	{
205	  IDLE_MAP_NAME, g_idle_map,
206	  sizeof(g_idle_map) / sizeof(g_idle_map[0]), NULL, NULL
207	};
208	
209	static const struct keyctx_s g_approval_ctx =
210	{
211	  "approval", g_approval_map,
212	  sizeof(g_approval_map) / sizeof(g_approval_map[0]), NULL, NULL
213	};
214	
215	void keyctx_push(const struct keyctx_s *ctx)
216	{
217	  if (s_ctx_depth < sizeof(s_ctx_stack) / sizeof(s_ctx_stack[0]))
218	    {
219	      s_ctx_stack[s_ctx_depth++] = ctx;
220	      if (ctx->enter != NULL)
221	        {
222	          ctx->enter();
223	        }
224	    }
225	}
226	
227	void keyctx_pop(void)
228	{
229	  if (s_ctx_depth > 0)
230	    {
231	      const struct keyctx_s *ctx = s_ctx_stack[--s_ctx_depth];
232	      if (ctx->leave != NULL)
233	        {
234	          ctx->leave();
235	        }
236	    }
237	}
238	
239	static const struct keymap_s *keymap_lookup(uint32_t keys,
240	                                            enum gesture_e g,
241	                                            const char **which)
242	{
243	  unsigned int i;
244	
245	  for (i = s_ctx_depth; i > 0; i--)
246	    {
247	      const struct keyctx_s *ctx = s_ctx_stack[i - 1];
248	      unsigned int j;
249	
250	      for (j = 0; j < ctx->nmap; j++)
251	        {
252	          if (ctx->map[j].keys == keys && ctx->map[j].gesture == g)
253	            {
254	              if (which != NULL)
255	                {
256	                  *which = ctx->name;
257	                }
258	
259	              return &ctx->map[j];
260	            }
261	        }
262	    }
263	
264	  for (i = 0; i < g_global_ctx.nmap; i++)
265	    {
266	      if (g_global_ctx.map[i].keys == keys &&
267	          g_global_ctx.map[i].gesture == g)
268	        {
269	          if (which != NULL)
270	            {
271	              *which = g_global_ctx.name;
272	            }
273	
274	          return &g_global_ctx.map[i];
275	        }
276	    }
277	
278	  return NULL;
279	}
