281	/****************************************************************************
282	 * Actions
283	 *
284	 * The key map reports an application intent, not a button press.  The entry
285	 * points arrive through remote_ctrl_register_input() and are the only thing
286	 * this adapter knows about the application: decide / pending / scroll /
287	 * model-next / new-session.  Each action just forwards to the callback it
288	 * was handed; the semantics (and any "nothing pending" feedback) live in
289	 * ai_agent, never here.
290	 ****************************************************************************/
291	
292	static remote_decide_fn s_decide;
293	static remote_pending_fn s_pending;
294	static remote_scroll_fn s_scroll;
295	static remote_action_fn s_model_next;
296	static remote_action_fn s_session_new;
297	static void *s_ctx;
298	
299	static void action_cancel(void)
300	{
301	  printf("[key] cancel\n");
302	}
303	
304	static void action_once(void)
305	{
306	  if (s_decide != NULL)
307	    {
308	      s_decide(REMOTE_DECISION_ONCE, s_ctx);
309	    }
310	  else
311	    {
312	      printf("[key] once (no input adapter)\n");
313	    }
314	}
315	
316	static void action_deny(void)
317	{
