693	int bk7258_buttons_input_initialize(void)
694	{
695	  pthread_t tid;
696	  pthread_attr_t attr;
697	  int ret;
698	
699	  pthread_attr_init(&attr);
700	  /* 4 KB was enough for the bare /dev/btn0 poll loop, but the key path now
701	   * fans out into ai_agent's remote_ctrl decide/scroll callbacks, which hop
702	   * into LVGL via lv_async_call() (lv_malloc + lv_timer_create) underneath a
703	   * printf/syslog formatting chain.  That depth overflows 4 KB and silently
704	   * drops the UI update: buttons register in the log but the screen never
705	   * changes.  32 KB matches the vela_tls floor and leaves comfortable
706	   * headroom; the heap arena is ~8 MB so the cost is negligible. */
707	  pthread_attr_setstacksize(&attr, 32768);
708	  ret = pthread_create(&tid, &attr, key_thread, NULL);
709	  pthread_attr_destroy(&attr);
710	  return ret == 0 ? 0 : -EIO;
711	}
