/*
 * time_sync.c — 把系统时钟对齐到网络时间。
 *
 * 为什么需要应用自己拉起 NTP:板级 AP 构建里 apps/netutils/netinit 的
 * ntpc_start() 挂在 netinit_net_bringup() 内,而该函数要求
 * NETINIT_HAVE_NETDEV(AP 没有 netdev,网络走 usrsock 到 CP),所以
 * 开机根本不会启动 NTP;Wi-Fi 又是用户后敲 `wapi connect` 才起来的。
 * 结果是时钟停在固件里的初始值,待机时钟显示错误日期/时间,HTTPS 证书
 * 也可能因为时钟偏移而失效。
 *
 * 这里起一个轻量监督线程:每 CHECK_INTERVAL_SEC 秒看一眼有没有可路由
 * IPv4,有就确保 NTP 守护在跑。ntpc_start() 自身幂等(NTP_RUNNING 时直接
 * 返回 pid),NTP 守护按 CONFIG_NETUTILS_NTPCLIENT_STAY_ON 每 60s 轮询,
 * 首次成功后持续校准,所以这里不需要反复 settimeofday。
 */

#include <nuttx/config.h>

#include "time_sync.h"
#include "network_manager.h"
#include "agent_compat.h"

#include <pthread.h>
#include <stdbool.h>
#include <syslog.h>
#include <unistd.h>

#ifdef CONFIG_NETUTILS_NTPCLIENT
#  include "netutils/ntpclient.h"
#endif

static const char* TAG = "time_sync";

#define CHECK_INTERVAL_SEC 30

static pthread_t s_thread;
static bool s_started;

static void* time_sync_task(void* arg)
{
    (void)arg;
    int last_pid = -1;

    while (1) {
        if (!network_is_connected()) {
            sleep(5);
            continue;
        }

#ifdef CONFIG_NETUTILS_NTPCLIENT
        /* Idempotent: returns the running daemon's pid, or restarts it if it
         * exited after exhausting its retries (e.g. Wi-Fi came up before DNS
         * was usable).  Log on pid change only -- this loop runs forever. */
        int pid = ntpc_start();
        if (pid != last_pid) {
            if (pid >= 0) {
                syslog(LOG_INFO,
                    "[%s] NTP daemon started (pid=%d), clock will follow\n",
                    TAG, pid);
            } else {
                syslog(LOG_WARNING, "[%s] ntpc_start failed: %d\n", TAG, pid);
            }
            last_pid = pid;
        }
#else
        static bool warned;
        if (!warned) {
            syslog(LOG_WARNING,
                "[%s] CONFIG_NETUTILS_NTPCLIENT is off; no time sync\n", TAG);
            warned = true;
        }
#endif

        sleep(CHECK_INTERVAL_SEC);
    }

    return NULL;
}

int time_sync_start(void)
{
    if (s_started) {
        return 0;
    }

    int ret = pthread_create(&s_thread, NULL, time_sync_task, NULL);
    if (ret != 0) {
        syslog(LOG_WARNING, "[%s] pthread_create failed: %d\n", TAG, ret);
        return -ret;
    }

    s_started = true;
    syslog(LOG_INFO, "[%s] supervisor started (waits for the link)\n", TAG);
    return 0;
}

