#include <nuttx/config.h>

#include "time_sync.h"
#include "network_manager.h"
#include "agent_compat.h"

#include <stdbool.h>
#include <syslog.h>
#include <unistd.h>

#ifdef CONFIG_NETUTILS_NTPCLIENT
#  include "netutils/ntpclient.h"
#endif

static const char* TAG = "time_sync";

#define CHECK_INTERVAL_SEC 30

/* 监督线程只做“看一眼链路 + 幂等拉起 ntpc”,不需要大栈,但 getifaddrs 有
 * 一定栈开销,统一走 agent_task_create(最小 4096)。 */
#define TIME_SYNC_STACK 4096
#define TIME_SYNC_PRIO 100

static bool s_started;

static void* time_sync_task(void* arg)
{
    (void)arg;
    int last_pid = -1;

    while (1) {
        if (!network_is_connected()) {
            sleep(5);
            continue;
        }

#ifdef CONFIG_NETUTILS_NTPCLIENT
        /* Idempotent: returns the running daemon's pid, or restarts it if it
         * exited after exhausting its retries (e.g. Wi-Fi came up before DNS
         * was usable).  Log on pid change only -- this loop runs forever. */
        int pid = ntpc_start();
        if (pid != last_pid) {
            if (pid >= 0) {
                syslog(LOG_INFO,
                    "[%s] NTP daemon started (pid=%d), clock will follow\n",
                    TAG, pid);
            } else {
                syslog(LOG_WARNING, "[%s] ntpc_start failed: %d\n", TAG, pid);
            }
            last_pid = pid;
        }
#else
        static bool warned;
        if (!warned) {
            syslog(LOG_WARNING,
                "[%s] CONFIG_NETUTILS_NTPCLIENT is off; no time sync\n", TAG);
            warned = true;
        }
#endif

        sleep(CHECK_INTERVAL_SEC);
    }

    return NULL;
}

int time_sync_start(void)
{
    if (s_started) {
        return 0;
    }

    int ret = agent_task_create(time_sync_task, "time_sync",
        TIME_SYNC_STACK, NULL, TIME_SYNC_PRIO);
    if (ret != OK) {
        syslog(LOG_WARNING, "[%s] task create failed\n", TAG);
        return -1;
    }

    s_started = true;
    syslog(LOG_INFO, "[%s] supervisor started (waits for the link)\n", TAG);
    return 0;
}

